<section class="container section deals-section"><div class="section-heading"><div><p class="eyebrow accent-eyebrow"><?php esc_html_e( 'Limited time', 'souqify' ); ?></p><h2><?php esc_html_e( 'Flash Deals', 'souqify' ); ?> <span aria-hidden="true">🔥</span></h2></div><div class="countdown" data-countdown="24:00:00"><span class="countdown-label"><?php esc_html_e( 'Ends in', 'souqify' ); ?></span><strong class="countdown-time">24:00:00</strong></div></div><?php if ( class_exists( 'WooCommerce' ) ) : ?><div class="products-row"><?php $deal_query = new WP_Query( array( 'post_type' => 'product', 'posts_per_page' => 4, 'post_status' => 'publish', 'meta_query' => array( array( 'key' => '_sale_price', 'value' => 0, 'compare' => '>', 'type' => 'NUMERIC' ) ) ) ); if ( $deal_query->have_posts() ) { while ( $deal_query->have_posts() ) { $deal_query->the_post(); get_template_part( 'template-parts/product/product-card' ); } wp_reset_postdata(); } else { echo '<p class="no-products">' . esc_html__( 'Add sale products in WooCommerce to display them here.', 'souqify' ) . '</p>'; } ?></div><?php endif; ?></section>
